from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

def t(slug, title, cat, answer, need, choose, wrong, detail, faqs, kw=None, img="orbit-essential-set-3"):
    return dict(slug=slug, title=title, cat=cat, answer=answer, need=need,
                choose=choose, wrong=wrong, detail=detail, faqs=faqs,
                kw=kw or title.split(":")[0].strip(), img=img)

