def esc(s):
    return s.replace("\\", "\\\\").replace("`", "\\`").replace("${", "\\${")

def arr(items):
    return "[\n      " + ",\n      ".join(f"`{esc(i)}`" for i in items) + ",\n    ]"

def faqs_ts(pairs):
    return "[\n      " + ",\n      ".join(
        f'{{ q: `{esc(q)}`, a: `{esc(a)}` }}' for q, a in pairs
    ) + ",\n    ]"

